// Desbloqueo de audio para iOS: se debe llamar de forma SÍNCRONA dentro del
// propio manejador de clic (antes de cualquier setTimeout), para que Safari
// asocie la reproducción de audio (aunque llegue con un pequeño retraso) con
// el toque real del usuario y no la bloquee.
function unlockAudioTap() {
  try {
    const silentAudio = new Audio("data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA=");
    silentAudio.volume = 0;
    silentAudio.play().catch(() => {});
  } catch (e) {}
  try {
    const u = new SpeechSynthesisUtterance("");
    u.volume = 0;
    window.speechSynthesis.speak(u);
  } catch (e) {}
}

// ---- Voz clonada (ElevenLabs) ----
// Llama al endpoint serverless /api/tts (que vive fuera de este componente, en Vercel)
// donde se guarda la API key de ElevenLabs de forma segura y se usa tu Voice ID clonado.
// Si el endpoint no existe o falla (por ejemplo, corriendo en el preview de Claude.ai,
// donde no hay backend), devuelve false y el que llama usa la voz nativa del navegador
// (SpeechSynthesisUtterance) como respaldo automático.
let _voiceSource = null;
let _voiceGain = null;
// Configuración global del locutor (volumen / silencio), persistida
const ANNOUNCER_KEY = "losmalucos-announcer";
let announcerSettings = { volume: 100, muted: false };
try {
  const saved = JSON.parse(localStorage.getItem(ANNOUNCER_KEY) || "{}");
  if (typeof saved.volume === "number") announcerSettings.volume = saved.volume;
  if (typeof saved.muted === "boolean") announcerSettings.muted = saved.muted;
} catch (e) {}

function saveAnnouncerSettings() {
  try { localStorage.setItem(ANNOUNCER_KEY, JSON.stringify(announcerSettings)); } catch (e) {}
}

function setAnnouncerVolume(v) {
  announcerSettings.volume = v;
  saveAnnouncerSettings();
  if (_voiceGain) { try { _voiceGain.gain.value = v / 100; } catch (e) {} }
  if (_masterGain && !announcerSettings.muted) { try { _masterGain.gain.value = v / 100; } catch (e) {} }
}

function setAnnouncerMuted(m) {
  announcerSettings.muted = m;
  saveAnnouncerSettings();
  if (m && _voiceSource) { try { _voiceSource.stop(); } catch (e) {} }
  if (m) { try { window.speechSynthesis.cancel(); } catch (e) {} }
  if (_masterGain) { try { _masterGain.gain.value = m ? 0 : announcerSettings.volume / 100; } catch (e) {} }
}

const _audioCache = new Map();

// Algunos nombres los confunde el locutor con inglés (ej: "Marlene" suena como
// nombre en inglés/alemán). Aquí se corrige la ortografía SOLO para lo que
// escucha el locutor (en pantalla el nombre se sigue viendo normal), agregando
// tildes que fuerzan la pronunciación correcta en español.
// Para agregar más casos: escribe el nombre tal cual lo escribes en la app
// (en minúscula) a la izquierda, y cómo debe "leerlo" el locutor a la derecha.
const TTS_NAME_FIXES = {
  "marlene": "Marléne",
  "guillermo": "Guiyermo",
  "rayó": "Ra-yó",
};
function ttsSafeText(text) {
  if (!text) return text;
  let out = text;
  for (const [wrong, fixed] of Object.entries(TTS_NAME_FIXES)) {
    const re = new RegExp(`\\b${wrong}\\b`, "gi");
    out = out.replace(re, fixed);
  }
  return out;
}

async function fetchAndDecodeTTS(rawText) {
  const text = ttsSafeText(rawText);
  if (_audioCache.has(text)) return _audioCache.get(text);
  const res = await fetch("/api/tts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ text }),
  });
  if (!res.ok) return null;
  const arrayBuffer = await res.arrayBuffer();
  if (!arrayBuffer || arrayBuffer.byteLength === 0) return null;
  const ctx = getAudioCtx();
  const audioBuffer = await ctx.decodeAudioData(arrayBuffer);
  _audioCache.set(text, audioBuffer);
  return audioBuffer;
}

// Descarga y decodifica por adelantado, sin reproducir, para que suene instantáneo
// la primera vez que se presione un botón (ej: nombres de jugadores al iniciar la partida)
function preloadSpeak(text) {
  if (!text || announcerSettings.muted) return;
  fetchAndDecodeTTS(text).catch(() => {});
}

async function elevenSpeak(text, onEnd) {
  if (announcerSettings.muted) {
    if (onEnd) onEnd();
    return true;
  }
  try {
    const audioBuffer = await fetchAndDecodeTTS(text);
    if (!audioBuffer) return false;
    const ctx = getAudioCtx();
    if (_voiceSource) {
      try { _voiceSource.stop(); } catch (e) {}
    }
    const source = ctx.createBufferSource();
    source.buffer = audioBuffer;
    const gainNode = ctx.createGain();
    gainNode.gain.value = announcerSettings.volume / 100;
    source.connect(gainNode);
    gainNode.connect(ctx.destination);
    _voiceSource = source;
    _voiceGain = gainNode;
    if (onEnd) source.onended = onEnd;
    source.start(0);
    return true;
  } catch (e) {
    return false;
  }
}

// Helper para dibujar rectángulos redondeados en canvas
// Primera letra en mayúscula, el resto en minúscula (para campos de nombre)
function capName(s) {
  if (!s) return s;
  return s.charAt(0).toUpperCase() + s.slice(1).toLowerCase();
}

function roundRect(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

