// AudioContext persistente que se desbloquea con el primer toque
let _ctx = null;
let _masterGain = null;

// Recuerda cuál fue el último índice de frase usado en cada "pool" (por nombre),
// para que ninguna frase se repita dos veces seguidas.
const _lastPhraseIdx = {};
const pickVaried = (poolKey, total) => {
  if (total <= 1) return 0;
  let idx = Math.floor(Math.random() * total);
  if (idx === _lastPhraseIdx[poolKey]) {
    idx = (idx + 1 + Math.floor(Math.random() * (total - 1))) % total;
  }
  _lastPhraseIdx[poolKey] = idx;
  return idx;
};

const getAudioCtx = () => {
  if (!_ctx) {
    _ctx = new (window.AudioContext || window.webkitAudioContext)();
  }
  if (_ctx.state === "suspended") {
    _ctx.resume();
  }
  if (_ctx.state === "interrupted") {
    _ctx.resume();
  }
  return _ctx;
};

// Nodo de ganancia maestro: todos los efectos de sonido (oscilador/ruido) se conectan
// aquí en vez de directo a ctx.destination, así el slider de volumen y el mute
// controlan también los efectos de sonido, no solo la voz del locutor.
const getMasterGain = (ctx) => {
  if (!_masterGain || _masterGain.context !== ctx) {
    _masterGain = ctx.createGain();
    _masterGain.gain.value = announcerSettings.muted ? 0 : announcerSettings.volume / 100;
    _masterGain.connect(ctx.destination);
  }
  return _masterGain;
};

// Clic de teclado realista: ruido blanco filtrado + golpe grave corto
const playRealisticKeyClick = () => {
  if (announcerSettings.muted) return;
  try {
    const ctx = getAudioCtx();
    const now = ctx.currentTime;

    // Ruido blanco (el "clic" en sí, como una tecla real)
    const bufferSize = Math.floor(ctx.sampleRate * 0.03);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufferSize, 2);
    }
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;

    const bandpass = ctx.createBiquadFilter();
    bandpass.type = "bandpass";
    bandpass.frequency.setValueAtTime(2800 + Math.random() * 800, now);
    bandpass.Q.setValueAtTime(1.2, now);

    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0.5, now);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.03);

    noise.connect(bandpass); bandpass.connect(noiseGain); noiseGain.connect(getMasterGain(ctx));
    noise.start(now); noise.stop(now + 0.03);

    // Golpe grave corto (cuerpo del clic, da sensación de "tecla física")
    const thock = ctx.createOscillator();
    const thockGain = ctx.createGain();
    thock.type = "sine";
    thock.frequency.setValueAtTime(150 + Math.random() * 25, now);
    thock.frequency.exponentialRampToValueAtTime(85, now + 0.04);
    thockGain.gain.setValueAtTime(0.13, now);
    thockGain.gain.exponentialRampToValueAtTime(0.001, now + 0.05);
    thock.connect(thockGain); thockGain.connect(getMasterGain(ctx));
    thock.start(now); thock.stop(now + 0.05);
  } catch (e) {}
};

// Golpe de ficha de dominó al anotar puntos (clack de madera/resina + rebote)
const playDominoClack = () => {
  if (announcerSettings.muted) return;
  try {
    const ctx = getAudioCtx();
    const now = ctx.currentTime;

    // Golpe seco de contacto (ficha golpeando la mesa)
    const bufferSize = Math.floor(ctx.sampleRate * 0.02);
    const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < bufferSize; i++) {
      data[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufferSize, 3);
    }
    const noise = ctx.createBufferSource();
    noise.buffer = buffer;
    const bandpass = ctx.createBiquadFilter();
    bandpass.type = "bandpass";
    bandpass.frequency.setValueAtTime(3500, now);
    bandpass.Q.setValueAtTime(0.9, now);
    const noiseGain = ctx.createGain();
    noiseGain.gain.setValueAtTime(0.35, now);
    noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.02);
    noise.connect(bandpass); bandpass.connect(noiseGain); noiseGain.connect(getMasterGain(ctx));
    noise.start(now); noise.stop(now + 0.02);

    // Cuerpo del golpe: resonancia grave corta tipo "toc" de mesa
    const body = ctx.createOscillator();
    const bodyGain = ctx.createGain();
    body.type = "triangle";
    body.frequency.setValueAtTime(220, now);
    body.frequency.exponentialRampToValueAtTime(110, now + 0.05);
    bodyGain.gain.setValueAtTime(0.22, now);
    bodyGain.gain.exponentialRampToValueAtTime(0.001, now + 0.07);
    body.connect(bodyGain); bodyGain.connect(getMasterGain(ctx));
    body.start(now); body.stop(now + 0.07);

    // Pequeño rebote (la ficha asentándose sobre la mesa)
    setTimeout(() => {
      try {
        const ctx2 = getAudioCtx();
        const t = ctx2.currentTime;
        const bufferSize2 = Math.floor(ctx2.sampleRate * 0.012);
        const buffer2 = ctx2.createBuffer(1, bufferSize2, ctx2.sampleRate);
        const data2 = buffer2.getChannelData(0);
        for (let i = 0; i < bufferSize2; i++) {
          data2[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / bufferSize2, 3);
        }
        const noise2 = ctx2.createBufferSource();
        noise2.buffer = buffer2;
        const bandpass2 = ctx2.createBiquadFilter();
        bandpass2.type = "bandpass";
        bandpass2.frequency.setValueAtTime(2800, t);
        const noiseGain2 = ctx2.createGain();
        noiseGain2.gain.setValueAtTime(0.15, t);
        noiseGain2.gain.exponentialRampToValueAtTime(0.001, t + 0.015);
        noise2.connect(bandpass2); bandpass2.connect(noiseGain2); noiseGain2.connect(getMasterGain(ctx2));
        noise2.start(t); noise2.stop(t + 0.015);
      } catch (e) {}
    }, 45);
  } catch (e) {}
};

const playBeep = (freq, type, duration, volume) => {
  if (announcerSettings.muted) return;
  try {
    const ctx = getAudioCtx();
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.connect(gain); gain.connect(getMasterGain(ctx));
    osc.type = type || "sine";
    osc.frequency.setValueAtTime(freq, ctx.currentTime);
    gain.gain.setValueAtTime(volume || 0.18, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + duration);
  } catch(e) {}
};

function SlotNumber({ value, color, fontSize = 64 }) {
  const [display, setDisplay] = useState(value);
  const [rolling, setRolling] = useState(false);
  const [prev, setPrev] = useState(value);

  const playTick = (count) => {
    if (announcerSettings.muted) return;
    try {
      const ctx = getAudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain); gain.connect(getMasterGain(ctx));
      osc.type = "triangle";
      const freq = 200 + (count / 11) * 600;
      osc.frequency.setValueAtTime(freq, ctx.currentTime);
      gain.gain.setValueAtTime(0.18, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.05);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 0.05);
    } catch(e) {}
  };

  useEffect(() => {
    if (value === prev) return;
    setPrev(value);
    setRolling(true);
    let count = 0;
    const interval = setInterval(() => {
      setDisplay(Math.floor(Math.random() * 99));
      playTick(count);
      count++;
      if (count >= 12) {
        clearInterval(interval);
        setDisplay(value);
        setRolling(false);
      }
    }, 55);
    return () => clearInterval(interval);
  }, [value]);

  return (
    <div style={{
      fontFamily: "'Orbitron', sans-serif",
      fontSize: fontSize, fontWeight: 900,
      color: rolling ? "#FFD700" : color,
      lineHeight: "1", textAlign: "center",
      display:"flex", alignItems:"center", justifyContent:"center",
      letterSpacing: 1,
      textShadow: rolling
        ? "0 0 10px #FFD700, 0 0 22px #FFD700aa"
        : `0 0 10px ${color}, 0 0 22px ${color}aa, 0 0 40px ${color}66`,
      transition: "color 0.2s",
    }}>
      {display}
    </div>
  );
}

